  q17 -> (s^2 - mz2*t + s*t)^(-1), 
  q18 -> (mw2^2*s - 2*mw2*s^2 + s^3 - 6*mw2*s*t + 2*s^2*t - 4*mw2*t^2 + 
     s*t^2)^(-1), q19 -> (mz2^2*s - 2*mz2*s*t - 4*mz2*t^2 + s*t^2)^(-1), 
  q20 -> (mz2^2*s - 2*mz2*s^2 + s^3 - 6*mz2*s*t + 2*s^2*t - 4*mz2*t^2 + 
     s*t^2)^(-1)}}
